package main

import (
	"database/sql"
)

type MyErr struct{}

func (*MyErr) Error() string { return "x" }

// returning external type (non-error), not the issue
func a() *MyErr {
	return &MyErr{}
}

// simple direct return of err from external pkg
func b() error {
	_, err := sql.Open("", "")
	return err
}

// direct external call return
func c() (*sql.DB, error) {
	return sql.Open("", "")
}

// assign then return
func d() (*sql.DB, error) {
	db, err := sql.Open("", "")
	return db, err
}

// local error type that is returned
type localErr struct{}
func (*localErr) Error() string { return "l" }

func e() error {
	return &localErr{}
}

// error from interface method
type Storer interface {
	Store() error
}

func f(s Storer) error {
	return s.Store()
}

// chained calls through internal functions
func helper() error {
	_, err := sql.Open("", "")
	return err
}

func g() error {
	return helper() // helper is internal, should not be reported
}

// through multiple external returns
func h() error {
	err := externalFunc()
	if err != nil {
		return err
	}
	return nil
}

func externalFunc() error {
	return nil // local
}

func main() {}
EOF
