		flagDiff       = fs.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
		flagFix        = fs.Bool("fix", false, "apply all suggested fixes")
		flagFlags      = fs.Bool("flags", false, "print analyzer flags in JSON")
		flagJSON       = fs.Bool("json", false, "emit JSON output")
		flagMemProfile = fs.String("memprofile", "", "write memory profile to this file")
		flagSource     = fs.Bool("source", false, "no effect (deprecated)")
		flagTags       = fs.String("tags", "", "no effect (deprecated)")
		flagTest       = fs.Bool("test", true, "indicates whether test files should be analyzed, too")
		flagTrace      = fs.String("trace", "", "write trace log to this file")
		flagV2         = fs.Bool("v", false, "no effect (deprecated)")
	)
	_ = flagAll
	_ = flagC
	_ = flagCPUProfile
	_ = flagDiff
	_ = flagFix
	_ = flagMemProfile
	_ = flagSource
	_ = flagTags
	_ = flagTest
	_ = flagTrace
	_ = flagV2
	_ = flagDebug

	fs.Usage = func() {
		printUsage(os.Stderr)
	}

	// Allow "-V" (no value) style to return the special Go convention error.
	// Pre-process args like the analysis framework does for -V.
	args := os.Args[1:]
	// Detect -V without value, like the real tool.
	for _, a := range args {
		if a == "-V" || a == "--V" {
			fmt.Fprintln(os.Stderr, "wrapcheck: unsupported flag value: -V=true (use -V=full)")
			return 1
		}
	}

	if err := fs.Parse(args); err != nil {
		// flag.ContinueOnError prints the error & usage; replicate wrapcheck style.
		printUsage(os.Stderr)
		return 2
	}

	if *flagFlags {
		printFlagsJSON(fs)
		return 0
	}

	if *flagV != "" {
		return printVersion(*flagV)
