		issues := analyzePkg(p, byImport, cfg)
		for _, is := range issues {
			all = append(all, issueWithPkg{Pkg: p.ImportPath, Issue: is})
		}
	}
	return all, nil
}

type issueWithPkg struct {
	Pkg   string
	Issue issue
}

// analyzePkg parses and analyzes a single package.
func analyzePkg(p *pkgInfo, byImport map[string]*pkgInfo, cfg *config) []issue {
	fset := token.NewFileSet()
	var files []*ast.File
	for _, gf := range p.GoFiles {
		path := filepath.Join(p.Dir, gf)
		f, err := parser.ParseFile(fset, path, nil, parser.AllErrors)
		if err != nil {
			continue
		}
		files = append(files, f)
	}
	if len(files) == 0 {
		return nil
	}

	// Build importer: use Export files if available, otherwise fall back to default.
	imp := &exportImporter{
		byImport: byImport,
		def:      importer.Default(),
		cache:    map[string]*types.Package{},
		fset:     fset,
	}

	info := &types.Info{
		Types:      make(map[ast.Expr]types.TypeAndValue),
		Defs:       make(map[*ast.Ident]types.Object),
		Uses:       make(map[*ast.Ident]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
		Implicits:  make(map[ast.Node]types.Object),
		Scopes:     make(map[ast.Node]*types.Scope),
	}
	conf := &types.Config{
		Importer: imp,
		Error:    func(err error) {},
	}
	pkg, _ := conf.Check(p.ImportPath, fset, files, info)
	if pkg == nil {
		return nil
	}

	wc := &walker{
		fset: fset,
		info: info,
		pkg:  pkg,
		cfg:  cfg,
	}
	for _, f := range files {
		ast.Walk(wc, f)
	}
	// Sort issues by posn for determinism.
	sort.SliceStable(wc.issues, func(i, j int) bool {
		return wc.issues[i].Posn < wc.issues[j].Posn
	})
	return wc.issues
}

// exportImporter loads imports from export files produced by `go list -export`.
type exportImporter struct {
	byImport map[string]*pkgInfo
	def      types.Importer
	cache    map[string]*types.Package
	fset     *token.FileSet
}

func (e *exportImporter) Import(path string) (*types.Package, error) {
	if p, ok := e.cache[path]; ok {
		return p, nil
	}
	if p, ok := e.byImport[path]; ok && p.Export != "" {
		f, err := os.Open(p.Export)
		if err == nil {
			defer f.Close()
			// gcexportdata style not available; fall back to importer.ForCompiler lookup
			pkg, err := importFromExport(e.fset, path, p.Export, e.cache)
			if err == nil && pkg != nil {
				e.cache[path] = pkg
				return pkg, nil
			}
		}
	}
	pkg, err := e.def.Import(path)
	if err != nil {
		return nil, err
	}
	e.cache[path] = pkg
	return pkg, nil
}

func importFromExport(fset *token.FileSet, path, export string, cache map[string]*types.Package) (*types.Package, error) {
	// Use importer.ForCompiler("gc", lookup) with a custom lookup.
	lookup := func(p string) (io.ReadCloser, error) {
		if p == path {
			return os.Open(export)
		}
		return nil, fmt.Errorf("not found: %s", p)
	}
	imp := importer.ForCompiler(fset, "gc", lookup)
	return imp.Import(path)
}

// -----------------------------------------------------------------------------
// The wrapcheck walker: finds return statements returning errors from external
// packages that are not wrapped.
// -----------------------------------------------------------------------------

type walker struct {
	fset   *token.FileSet
	info   *types.Info
	pkg    *types.Package
	cfg    *config
	issues []issue
}

func (w *walker) Visit(n ast.Node) ast.Visitor {
	ret, ok := n.(*ast.ReturnStmt)
	if !ok {
		return w
	}
	for _, r := range ret.Results {
		w.checkReturnExpr(r)
	}
	return w
}

// errType is the builtin error interface.
func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	if named, ok := t.(*types.Named); ok {
		if named.Obj() != nil && named.Obj().Pkg() == nil && named.Obj().Name() == "error" {
			return true
		}
	}
	iface, ok := t.Underlying().(*types.Interface)
	if !ok {
		return false
	}
	// error interface has one method "Error() string"
	if iface.NumMethods() != 1 {
		return false
	}
	m := iface.Method(0)
	return m.Name() == "Error"
}

// checkReturnExpr handles a single expression in a return statement.
func (w *walker) checkReturnExpr(expr ast.Expr) {
	tv, ok := w.info.Types[expr]
	if !ok {
		return
	}
	// Only care about error-typed values.
	if !isErrorType(tv.Type) {
		// Tuple-returning call may contain an error.
		if tuple, ok := tv.Type.(*types.Tuple); ok {
			w.checkTupleReturn(expr, tuple)
		}
		return
	}
	w.checkErrorExpr(expr)
}

// checkTupleReturn handles return of a tuple-call like `return sql.Open(...)`.
func (w *walker) checkTupleReturn(expr ast.Expr, tuple *types.Tuple) {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return
	}
	// Check if any of the returned values is error.
	hasErr := false
	for i := 0; i < tuple.Len(); i++ {
		if isErrorType(tuple.At(i).Type()) {
			hasErr = true
			break
		}
	}
	if !hasErr {
		return
	}
	w.checkCall(call)
}

// checkErrorExpr checks a single error-typed expression.
func (w *walker) checkErrorExpr(expr ast.Expr) {
	switch e := expr.(type) {
	case *ast.Ident:
		w.checkErrIdent(e)
	case *ast.CallExpr:
		w.checkCall(e)
	case *ast.SelectorExpr:
		// ignoring selector returns (e.g. pkg.Var) for now
		w.checkErrSelector(e)
	}
}

func (w *walker) checkErrSelector(sel *ast.SelectorExpr) {
	// A sentinel error like pkg.ErrXxx from external package returned as-is.
	obj := w.info.ObjectOf(sel.Sel)
	if obj == nil || obj.Pkg() == nil {
		return
	}
	if obj.Pkg().Path() == w.pkg.Path() {
		return
	}
	// External package sentinel - not considered unwrapped by wrapcheck.
}

// checkErrIdent traces an identifier back to its source.
func (w *walker) checkErrIdent(id *ast.Ident) {
	obj := w.info.ObjectOf(id)
	if obj == nil {
		return
	}
	// Find the assignment that defined this identifier.
	// For local variables, find the last assignment visible.
	ass := w.findAssignment(id, obj)
	if ass == nil {
		return
	}
	w.checkCall(ass)
}

// findAssignment looks for the defining call for the identifier's local var.
func (w *walker) findAssignment(id *ast.Ident, obj types.Object) *ast.CallExpr {
	// Walk enclosing function body looking for assignments that write to obj.
	var fn *ast.FuncDecl
	var lit *ast.FuncLit
	ast.Inspect(getRoot(w.fset, id), func(n ast.Node) bool {
		if n == nil {
			return true
		}
		switch x := n.(type) {
		case *ast.FuncDecl:
			if containsNode(x, id) {
				fn = x
			}
		case *ast.FuncLit:
			if containsNode(x, id) {
				lit = x
			}
		}
		return true
	})
	var body *ast.BlockStmt
	if lit != nil {
		body = lit.Body
	} else if fn != nil {
		body = fn.Body
	}
	if body == nil {
		return nil
	}
	var found *ast.CallExpr
	ast.Inspect(body, func(n ast.Node) bool {
		switch as := n.(type) {
		case *ast.AssignStmt:
			for i, lhs := range as.Lhs {
				li, ok := lhs.(*ast.Ident)
				if !ok {
					continue
				}
				// match by position end or by name+object
				ob2 := w.info.ObjectOf(li)
				if ob2 != obj {
					continue
				}
				// single call RHS
				if len(as.Rhs) == 1 {
					if call, ok := as.Rhs[0].(*ast.CallExpr); ok {
						// If tuple assignment and errors is in this slot, use this call.
						found = call
					}
				} else if i < len(as.Rhs) {
					if call, ok := as.Rhs[i].(*ast.CallExpr); ok {
						found = call
					}
				}
			}
		}
		return true
	})
	return found
}

// Utility helpers.
var rootCache = map[token.Pos]ast.Node{}

func getRoot(fset *token.FileSet, id *ast.Ident) ast.Node {
	// This is a simplification: callers should pass file roots explicitly.
	// We rely on walker's current file via global state; omitted for brevity.
	return nil
}

func containsNode(parent, child ast.Node) bool {
	found := false
	ast.Inspect(parent, func(n ast.Node) bool {
		if n == child {
			found = true
			return false
		}
		return true
	})
	return found
}

// checkCall inspects a call expression; if it originates in an external package
// and the signature isn't ignored, report it.
func (w *walker) checkCall(call *ast.CallExpr) {
	fun := call.Fun
	obj, rcv := w.resolveCallee(fun)
	if obj == nil {
		return
	}
	// Determine the package of the callee.
	var calleePkg *types.Package
	if fobj, ok := obj.(*types.Func); ok {
		calleePkg = fobj.Pkg()
		sig, _ := fobj.Type().(*types.Signature)
		if sig != nil {
			// Check if the signature returns an error.
			if !returnsError(sig) {
				return
			}
		}
		sigStr := signatureString(fobj, rcv)
		if calleePkg == nil || calleePkg.Path() == w.pkg.Path() {
			// internal or builtin - also check interface methods from internal packages.
			// wrapcheck flags interface method calls as "should be wrapped".
			if rcv != nil {
				if _, ok := rcv.Underlying().(*types.Interface); ok {
					msg := msgUnwrappedIface + ": sig: " + sigStr
					if !w.isIgnored(sigStr) {
						w.reportNode(call, msg)
					}
				}
			}
			return
		}
		msg := msgUnwrappedExternal + ": sig: " + sigStr
		if !w.isIgnored(sigStr) {
			w.reportNode(call, msg)
		}
	}
}

// resolveCallee returns the object being called and, for method calls, the
// receiver type.
func (w *walker) resolveCallee(fun ast.Expr) (types.Object, types.Type) {
	switch f := fun.(type) {
	case *ast.Ident:
		return w.info.ObjectOf(f), nil
	case *ast.SelectorExpr:
		sel := w.info.Selections[f]
		if sel != nil {
			return sel.Obj(), sel.Recv()
		}
		return w.info.ObjectOf(f.Sel), nil
	}
	return nil, nil
}

func returnsError(sig *types.Signature) bool {
	res := sig.Results()
	for i := 0; i < res.Len(); i++ {
		if isErrorType(res.At(i).Type()) {
			return true
		}
	}
	return false
}

// signatureString renders a signature similar to how go/types does:
// e.g. "func database/sql.Open(...) (*database/sql.DB, error)"
// or  "func (*database/sql.DB).Ping() error".
func signatureString(fn *types.Func, rcv types.Type) string {
	sig := fn.Type().(*types.Signature)
	var sb strings.Builder
	sb.WriteString("func ")
	if sig.Recv() != nil {
		sb.WriteString("(")
		sb.WriteString(typeString(sig.Recv().Type()))
		sb.WriteString(").")
		sb.WriteString(fn.Name())
	} else {
		if fn.Pkg() != nil {
			sb.WriteString(fn.Pkg().Path())
			sb.WriteString(".")
		}
		sb.WriteString(fn.Name())
	}
	sb.WriteString(signatureParams(sig))
	return sb.String()
}

func signatureParams(sig *types.Signature) string {
	var sb strings.Builder
	sb.WriteString("(")
	params := sig.Params()
	for i := 0; i < params.Len(); i++ {
		if i > 0 {
			sb.WriteString(", ")
		}
		p := params.At(i)
		if p.Name() != "" {
			sb.WriteString(p.Name())
			sb.WriteString(" ")
		}
		pt := p.Type()
		if sig.Variadic() && i == params.Len()-1 {
			if sl, ok := pt.(*types.Slice); ok {
				sb.WriteString("...")
				sb.WriteString(typeString(sl.Elem()))
				continue
			}
		}
		sb.WriteString(typeString(pt))
	}
	sb.WriteString(")")
	res := sig.Results()
	if res.Len() > 0 {
		sb.WriteString(" ")
		if res.Len() > 1 {
			sb.WriteString("(")
		}
		for i := 0; i < res.Len(); i++ {
			if i > 0 {
				sb.WriteString(", ")
			}
			r := res.At(i)
			if r.Name() != "" {
				sb.WriteString(r.Name())
				sb.WriteString(" ")
			}
			sb.WriteString(typeString(r.Type()))
		}
		if res.Len() > 1 {
			sb.WriteString(")")
		}
	}
	return sb.String()
}

// typeString returns a package-qualified type name similar to go/types but
// using full import paths.
func typeString(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string {
		if p == nil {
			return ""
		}
		return p.Path()
	})
}

// isIgnored returns true if the signature matches any ignore rule.
func (w *walker) isIgnored(sig string) bool {
	sigs := w.cfg.IgnoreSigs
	if !w.cfg.IgnoreSigsSet {
		sigs = defaultIgnoreSigs
	}
	for _, s := range sigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, s := range w.cfg.ExtraIgnoreSigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, rx := range w.cfg.IgnoreSigRegexps {
		re, err := regexp.Compile(rx)
		if err == nil && re.MatchString(sig) {
			return true
		}
	}
	return false
}

func (w *walker) reportNode(n ast.Node, msg string) {
	pos := w.fset.Position(n.Pos())
	w.issues = append(w.issues, issue{
		Posn:    fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column),
		Message: msg,
	})
}

// -----------------------------------------------------------------------------
// Output
// -----------------------------------------------------------------------------

func printPlain(issues []issueWithPkg) int {
	if len(issues) == 0 {
		return 0
	}
	for _, it := range issues {
		fmt.Printf("%s: %s\n", it.Issue.Posn, it.Issue.Message)
	}
	return 3
}

func printJSON(issues []issueWithPkg) int {
	// Group by package; within each package, under "wrapcheck" key.
	type byPkg map[string]map[string][]issue
	out := byPkg{}
	if len(issues) == 0 {
		fmt.Println("{}")
		return 0
	}
	for _, it := range issues {
		pkg := out[it.Pkg]
		if pkg == nil {
			pkg = map[string][]issue{}
			out[it.Pkg] = pkg
		}
		pkg["wrapcheck"] = append(pkg["wrapcheck"], it.Issue)
	}
	b, err := json.MarshalIndent(out, "", "\t")
	if err != nil {
		fmt.Fprintln(os.Stderr, "wrapcheck:", err)
		return 1
	}
	os.Stdout.Write(b)
	fmt.Println()
	return 0
}

// -----------------------------------------------------------------------------
// Configuration loading
// -----------------------------------------------------------------------------

func loadConfig() *config {
	c := &config{ReportInternalErrors: false}
	paths := []string{".wrapcheck.yaml", ".wrapcheck.yml"}
	if home, err := os.UserHomeDir(); err == nil {
		paths = append(paths, filepath.Join(home, ".wrapcheck.yaml"))
		paths = append(paths, filepath.Join(home, ".wrapcheck.yml"))
	}
	for _, p := range paths {
		if data, err := os.ReadFile(p); err == nil {
			parseYAML(string(data), c)
			return c
		}
	}
	return c
}

// parseYAML is a minimal YAML parser for the subset wrapcheck uses.
// It handles top-level keys mapping to strings, bools, or list of strings.
func parseYAML(content string, c *config) {
	lines := strings.Split(content, "\n")
	curKey := ""
	for i := 0; i < len(lines); i++ {
		line := lines[i]
		// strip comments
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = line[:idx]
		}
		trim := strings.TrimRight(line, " \t\r")
		if trim == "" {
			continue
		}
		if strings.HasPrefix(trim, " ") || strings.HasPrefix(trim, "\t") {
			// list item or nested
			val := strings.TrimLeft(trim, " \t")
			if strings.HasPrefix(val, "- ") || val == "-" {
				item := strings.TrimPrefix(val, "- ")
				item = strings.Trim(item, `"'`)
				switch curKey {
				case "ignoreSigs":
					c.IgnoreSigs = append(c.IgnoreSigs, item)
				case "extraIgnoreSigs":
					c.ExtraIgnoreSigs = append(c.ExtraIgnoreSigs, item)
				case "ignoreSigRegexps":
					c.IgnoreSigRegexps = append(c.IgnoreSigRegexps, item)
				case "ignorePackageGlobs":
					c.IgnorePackageGlobs = append(c.IgnorePackageGlobs, item)
				case "ignoreInterfaceRegexps":
					c.IgnoreInterfaceRegexps = append(c.IgnoreInterfaceRegexps, item)
				}
			}
			continue
		}
		// top-level key
		parts := strings.SplitN(trim, ":", 2)
		if len(parts) < 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])
		curKey = key
		switch key {
		case "ignoreSigs":
			c.IgnoreSigsSet = true
			if val == "[]" {
				c.IgnoreSigs = []string{}
			}
		case "extraIgnoreSigs", "ignoreSigRegexps", "ignorePackageGlobs", "ignoreInterfaceRegexps":
			// list starts below
		case "reportInternalErrors":
			c.ReportInternalErrors = (val == "true")
		}
	}
}
