	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

// Configuration loaded from .wrapcheck.yaml.
type config struct {
	IgnoreSigs             []string
	ExtraIgnoreSigs        []string
	IgnoreSigRegexps       []string
	IgnorePackageGlobs     []string
	IgnoreInterfaceRegexps []string
	ReportInternalErrors   bool
	// whether IgnoreSigs was explicitly set in config
	IgnoreSigsSet bool
}

// FlagInfo mirrors the JSON produced by -flags.
type flagInfo struct {
	Name  string
	Bool  bool
	Usage string
}

// Issue represents a detected wrapcheck finding.
type issue struct {
	Posn    string `json:"posn"`
	Message string `json:"message"`
}

func main() {
	os.Exit(run())
}

func run() int {
	fs := flag.NewFlagSet("wrapcheck", flag.ContinueOnError)

	var (
		flagV          = fs.String("V", "", "print version and exit")
		flagAll        = fs.Bool("all", true, "no effect (deprecated)")
		flagC          = fs.Int("c", -1, "display offending line with this many lines of context")
		flagCPUProfile = fs.String("cpuprofile", "", "write CPU profile to this file")
		flagDebug      = fs.String("debug", "", "debug flags, any subset of \"fpstv\"")
		flagDiff       = fs.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
		flagFix        = fs.Bool("fix", false, "apply all suggested fixes")
		flagFlags      = fs.Bool("flags", false, "print analyzer flags in JSON")
		flagJSON       = fs.Bool("json", false, "emit JSON output")
		flagMemProfile = fs.String("memprofile", "", "write memory profile to this file")
		flagSource     = fs.Bool("source", false, "no effect (deprecated)")
		flagTags       = fs.String("tags", "", "no effect (deprecated)")
		flagTest       = fs.Bool("test", true, "indicates whether test files should be analyzed, too")
		flagTrace      = fs.String("trace", "", "write trace log to this file")
		flagV2         = fs.Bool("v", false, "no effect (deprecated)")
	)
	_ = flagAll
	_ = flagC
	_ = flagCPUProfile
	_ = flagDiff
	_ = flagFix
	_ = flagMemProfile
	_ = flagSource
	_ = flagTags
	_ = flagTest
	_ = flagTrace
	_ = flagV2
	_ = flagDebug

	fs.Usage = func() {
		printUsage(os.Stderr)
	}

	// Allow "-V" (no value) style to return the special Go convention error.
	// Pre-process args like the analysis framework does for -V.
	args := os.Args[1:]
	// Detect -V without value, like the real tool.
	for _, a := range args {
		if a == "-V" || a == "--V" {
			fmt.Fprintln(os.Stderr, "wrapcheck: unsupported flag value: -V=true (use -V=full)")
			return 1
		}
	}

	if err := fs.Parse(args); err != nil {
		// flag.ContinueOnError prints the error & usage; replicate wrapcheck style.
		printUsage(os.Stderr)
		return 2
	}

	if *flagFlags {
		printFlagsJSON(fs)
		return 0
	}

	if *flagV != "" {
		return printVersion(*flagV)
	}

	rest := fs.Args()
	if len(rest) == 0 {
		printUsage(os.Stderr)
		return 1
	}

	cfg := loadConfig()

	issues, loadErr := analyze(rest, cfg)
	if loadErr != nil {
		fmt.Fprintln(os.Stderr, "wrapcheck:", loadErr)
		return 1
	}

	if *flagJSON {
		return printJSON(issues)
	}
	return printPlain(issues)
}

func printUsage(w io.Writer) {
	fmt.Fprintln(w, "wrapcheck: Checks that errors returned from external packages are wrapped")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Usage: wrapcheck [-flag] [package]")
	fmt.Fprintln(w)
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Flags:")
	fmt.Fprintln(w, "  -V\tprint version and exit")
	fmt.Fprintln(w, "  -all")
	fmt.Fprintln(w, "    \tno effect (deprecated)")
	fmt.Fprintln(w, "  -c int")
	fmt.Fprintln(w, "    \tdisplay offending line with this many lines of context (default -1)")
	fmt.Fprintln(w, "  -cpuprofile string")
	fmt.Fprintln(w, "    \twrite CPU profile to this file")
	fmt.Fprintln(w, "  -debug string")
	fmt.Fprintln(w, "    \tdebug flags, any subset of \"fpstv\"")
	fmt.Fprintln(w, "  -diff")
	fmt.Fprintln(w, "    \twith -fix, don't update the files, but print a unified diff")
	fmt.Fprintln(w, "  -fix")
	fmt.Fprintln(w, "    \tapply all suggested fixes")
	fmt.Fprintln(w, "  -flags")
	fmt.Fprintln(w, "    \tprint analyzer flags in JSON")
	fmt.Fprintln(w, "  -json")
	fmt.Fprintln(w, "    \temit JSON output")
	fmt.Fprintln(w, "  -memprofile string")
	fmt.Fprintln(w, "    \twrite memory profile to this file")
	fmt.Fprintln(w, "  -source")
	fmt.Fprintln(w, "    \tno effect (deprecated)")
	fmt.Fprintln(w, "  -tags string")
	fmt.Fprintln(w, "    \tno effect (deprecated)")
	fmt.Fprintln(w, "  -test")
	fmt.Fprintln(w, "    \tindicates whether test files should be analyzed, too (default true)")
	fmt.Fprintln(w, "  -trace string")
