func run() int {
	fs := flag.NewFlagSet("wrapcheck", flag.ContinueOnError)

	var (
		flagV          = fs.String("V", "", "print version and exit")
		_              = fs.Bool("all", true, "no effect (deprecated)")
		_              = fs.Int("c", -1, "display offending line with this many lines of context")
		_              = fs.String("cpuprofile", "", "write CPU profile to this file")
		_              = fs.String("debug", "", "debug flags, any subset of \"fpstv\"")
		_              = fs.Bool("diff", false, "with -fix, don't update the files, but print a unified diff")
		_              = fs.Bool("fix", false, "apply all suggested fixes")
		flagFlags      = fs.Bool("flags", false, "print analyzer flags in JSON")
		flagJSON       = fs.Bool("json", false, "emit JSON output")
		_              = fs.String("memprofile", "", "write memory profile to this file")
		_              = fs.Bool("source", false, "no effect (deprecated)")
		_              = fs.String("tags", "", "no effect (deprecated)")
		_              = fs.Bool("test", true, "indicates whether test files should be analyzed, too")
		_              = fs.String("trace", "", "write trace log to this file")
		_              = fs.Bool("v", false, "no effect (deprecated)")
	)

	// Suppress default flag error output - we produce our own usage.
	fs.SetOutput(io.Discard)
	fs.Usage = func() { printUsage(os.Stderr) }

	args := os.Args[1:]
	// Detect -V without value, like the real tool.
	for _, a := range args {
		if a == "-V" || a == "--V" {
			fmt.Fprintln(os.Stderr, "wrapcheck: unsupported flag value: -V=true (use -V=full)")
			return 1
		}
	}

	if err := fs.Parse(args); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		printUsage(os.Stderr)
		return 2
	}

	if *flagFlags {
		printFlagsJSON()
		return 0
	}

	if *flagV != "" {
		return printVersion(*flagV)
	}

	rest := fs.Args()
	if len(rest) == 0 {
		printUsage(os.Stderr)
		return 1
	}

	cfg := loadConfig()

	issues, loadErr := analyze(rest, cfg)
	if loadErr != nil {
		if loadErr.Error() != "" {
			fmt.Fprintln(os.Stderr, "wrapcheck:", loadErr)
		}
		return 1
	}

	if *flagJSON {
		return printJSON(issues)
	}
	return printPlain(issues)
