	}
	return ""
}

// matchGlob does simple shell-style matching, supporting * and **.
func matchGlob(pattern, s string) bool {
	// Convert glob to regex.
	var sb strings.Builder
	sb.WriteString("^")
	i := 0
	for i < len(pattern) {
		c := pattern[i]
		switch c {
		case '*':
			if i+1 < len(pattern) && pattern[i+1] == '*' {
				sb.WriteString(".*")
				i += 2
			} else {
				sb.WriteString("[^/]*")
				i++
			}
		case '?':
			sb.WriteString(".")
			i++
		case '.', '+', '(', ')', '|', '[', ']', '{', '}', '^', '$', '\\\\':
			sb.WriteString("\\\\")
			sb.WriteByte(c)
			i++
		default:
			sb.WriteByte(c)
			i++
		}
	}
	sb.WriteString("$")
	re, err := regexp.Compile(sb.String())
	if err != nil {
		return false
	}
	return re.MatchString(s)
}'''
