			line = line[:idx]
		}
		trim := strings.TrimRight(line, " \\t\\r")
		if trim == "" {
			continue
		}
		// List item line (indented or unindented "- item")
		lstripped := strings.TrimLeft(trim, " \\t")
		if strings.HasPrefix(lstripped, "- ") || lstripped == "-" {
			item := strings.TrimPrefix(lstripped, "- ")
			item = strings.TrimSpace(item)
			// unquote
			if (strings.HasPrefix(item, "\\"") && strings.HasSuffix(item, "\\"")) ||
