		if w.funcLitDepth > 0 {
			return
		}
		if _, isCall := expr.(*ast.CallExpr); isCall {
			hasErr := false
			for i := 0; i < tuple.Len(); i++ {
				if isErrorType(tuple.At(i).Type()) {
					hasErr = true
					break
				}
			}
			if hasErr {
				w.checkCallReport(expr.(*ast.CallExpr), expr)
			}
		}
		return
	}'''
